import{_ as s,l as o,o as e,c as n,v as t,p as l,x as i,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"风险量化","description":"","frontmatter":{"title":"风险量化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/risk-quantification.md","filePath":"cs/risk-quantification.md","lastUpdated":1789023840000}'),p={name:"cs/risk-quantification.md"};function u(_,a,E,f,A,m){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="风险量化" tabindex="-1">风险量化 <a class="header-anchor" href="#风险量化" aria-label="Permalink to &quot;风险量化&quot;">​</a></h1><div class="epigraph"><p>风险是频率与损失的语言。FAIR 一类把情景写成可比较的分布，而不是红黄绿。数字差也会误导：没有暴露面与控制，CVSS 不能当唯一输入。</p><footer>—— 据 Freund and Jones, *Measuring and Managing Information Risk*（FAIR）；对照 NIST CSF；[CVE 与 CVSS](/cs/cve-cvss)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/usable-security">可用安全</a>说明人会绕过。缺口是<strong>决策语言</strong>：把情景量化以便排优先级。本课 FAIR 直觉，不假装精算完成。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>颜色标签不可加。缺口：情景、威胁共同体、抵抗强度、损失幅度。数据稀疏则给区间。</p><h3 id="不是金融定价" tabindex="-1">不是金融定价 <a class="header-anchor" href="#不是金融定价" aria-label="Permalink to &quot;不是金融定价&quot;">​</a></h3><p>不把期权或 LOB 搬进本课。</p><p><span class="marginnote">FAIR。零信任下一课是架构响应之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一条情景到损失。对照 CVSS 只是技术严重度。下一课零信任架构。</p>',12)),(e(),l(h,null,{default:i(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCEN%5B%22%E6%83%85%E6%99%AF%22%5D%20--%3E%20FREQ%5B%22%E9%A2%91%E7%8E%87%22%5D%0A%20%20SCEN%20--%3E%20MAG%5B%22%E6%8D%9F%E5%A4%B1%E5%B9%85%E5%BA%A6%22%5D%0A%20%20FREQ%20--%3E%20RISK%5B%22%E5%8F%AF%E6%AF%94%E8%BE%83%E7%9A%84%E9%A3%8E%E9%99%A9%22%5D%0A%20%20MAG%20--%3E%20RISK%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>给钱与工程一个接口。零信任是减少情景发生条件的架构。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造精确损失表。零信任架构下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可用安全之后，管理层要用可比较的风险。</li><li>情景、频率、幅度；CVSS 只是输入之一。</li><li>稀疏数据用区间，不用假精确。</li><li>下一课零信任架构。</li><li>出处：Freund and Jones, FAIR；NIST CSF；<a href="/cs/cve-cvss">cve-cvss</a>。</li></ul>',8))])}const b=s(p,[["render",u]]);export{q as __pageData,b as default};
